.fx-ckb{position:relative;width:min(920px,100%);height:560px;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 94%,var(--text))}.fx-ckb .pg{position:absolute;inset:0;padding:1.2em 1.5em;display:flex;flex-direction:column;gap:1em;overflow:hidden}
.fx-ckb .nv{display:flex;align-items:center;gap:1em;padding-bottom:.9em;border-bottom:1px solid var(--border)}
.fx-ckb .nv b{font:700 1.05em var(--font-heading);display:flex;align-items:center;gap:.5em}.fx-ckb .nv b::before{content:"";width:.9em;height:.9em;border-radius:30%;background:var(--accent)}
.fx-ckb .nv i{width:3.4em;height:.55em;border-radius:9px;background:var(--border)}.fx-ckb .nv i:nth-of-type(1){margin-left:auto}
.fx-ckb .pg h2{font-size:clamp(1.5em,4vw,2.1em);max-width:18ch;margin-top:.5em}
.fx-ckb .pg .lede{opacity:.66;max-width:44ch}
.fx-ckb .pg .row{display:flex;gap:.7em;flex-wrap:wrap;margin-top:.2em}
.fx-ckb .pg .sk{display:grid;grid-template-columns:repeat(3,1fr);gap:.8em;margin-top:auto}
.fx-ckb .pg .sk div{height:5.2em;border-radius:var(--radius);border:1px solid var(--border);background:linear-gradient(135deg,color-mix(in srgb,var(--primary) 10%,transparent),color-mix(in srgb,var(--accent) 12%,transparent))}
@media(max-width:560px){.fx-ckb .pg .sk{grid-template-columns:1fr 1fr}.fx-ckb .pg .sk div:nth-child(3){display:none}.fx-ckb .nv i{display:none}}
.fx-ckb .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.7em 1.15em;border-radius:var(--radius);font:600 .92em var(--font-body);cursor:pointer;border:1px solid var(--border);background:transparent;color:var(--text);transition:background calc(.2s/var(--speed)),color calc(.2s/var(--speed)),transform calc(.2s/var(--speed)),border-color calc(.2s/var(--speed))}
.fx-ckb .btn:hover{border-color:var(--primary);color:var(--primary)}
.fx-ckb .btn.pri{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}
.fx-ckb .btn.pri:hover{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-ckb .btn.acc{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fx-ckb .btn:active{transform:translateY(1px)}
.fx-ckb :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-ckb .pg .ft{margin-top:auto;display:flex;gap:1em;justify-content:space-between;align-items:center;font-size:.82em;opacity:.7;padding-top:.8em;border-top:1px solid var(--border)}
.fx-ckb .pg .ft button{all:unset;cursor:pointer;text-decoration:underline;text-underline-offset:3px;color:var(--primary);font-weight:700}
.fx-ckb .pg .ft button:focus-visible{outline:2px solid var(--accent)}
.fx-ckb .ck{position:absolute;left:1em;bottom:1em;width:min(460px,calc(100% - 2em));max-height:calc(100% - 2em);overflow:auto;padding:1.2em 1.3em;background:var(--surface);border:1px solid var(--border);border-radius:calc(var(--radius) + 2px);box-shadow:0 24px 48px -20px rgba(0,0,0,.45);transition:transform calc(.45s/var(--speed)) cubic-bezier(.2,.8,.2,1),opacity calc(.3s/var(--speed)),visibility 0s linear calc(.45s/var(--speed))}
.fx-ckb .ck.hide{transform:translateY(24px);opacity:0;visibility:hidden}
.fx-ckb .ck h3{font-size:1.15em;display:flex;align-items:center;gap:.5em}
.fx-ckb .ck h3 svg{width:1.2em;height:1.2em;stroke:var(--accent);fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.fx-ckb .ck p{font-size:.88em;opacity:.7;margin:.45em 0 .9em}
.fx-ckb .ck p a{color:var(--primary);text-underline-offset:3px}
.fx-ckb .ck .opts{display:none;gap:.1em;margin:0 0 1em;border-top:1px solid var(--border)}
.fx-ckb .ck.more .opts{display:grid}
.fx-ckb .ck .op{display:flex;justify-content:space-between;align-items:center;gap:1em;padding:.65em 0;border-bottom:1px solid var(--border);font-size:.88em;cursor:pointer}
.fx-ckb .ck .op small{display:block;opacity:.6;font-size:.9em}
.fx-ckb .ck .op input{appearance:none;flex:none;width:2.4em;height:1.4em;border-radius:99px;background:color-mix(in srgb,var(--text) 22%,transparent);position:relative;cursor:pointer;transition:background .25s}
.fx-ckb .ck .op input::after{content:"";position:absolute;top:.15em;left:.15em;width:1.1em;height:1.1em;border-radius:50%;background:#fff;transition:transform calc(.25s/var(--speed))}
.fx-ckb .ck .op input:checked{background:var(--primary)}.fx-ckb .ck .op input:checked::after{transform:translateX(1em)}.fx-ckb .ck .op input:disabled{opacity:.5;cursor:not-allowed}
.fx-ckb .ck .btns{display:flex;gap:.5em;flex-wrap:wrap}.fx-ckb .ck .btns .btn{flex:1 1 auto;padding:.6em .9em;font-size:.85em}
.fx-ckb .msg{position:absolute;left:1em;bottom:1em;font-size:.85em;padding:.6em .9em;border-radius:99px;background:var(--text);color:var(--surface);opacity:0;transform:translateY(8px);transition:all calc(.3s/var(--speed));pointer-events:none}
.fx-ckb .msg.on{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){.fx-ckb .ck,.fx-ckb .msg{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-ckb .btn.is-tap{border-color:var(--primary);color:var(--primary)}
.fx-ckb .btn.pri.is-tap{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}

