(function(){var root=document.querySelector('.fx-ckb'),ck=root.querySelector('.ck'),msg=root.querySelector('.msg'),mb=root.querySelector('[data-more]'),t;
function hide(m){ck.classList.add('hide');ck.setAttribute('aria-hidden','true');msg.textContent=m;msg.classList.add('on');clearTimeout(t);t=setTimeout(function(){msg.classList.remove('on')},2400)}
root.querySelectorAll('[data-a]').forEach(function(b){b.addEventListener('click',function(){hide(b.dataset.a==='all'?'Preferences saved: all cookies':'Preferences saved: essential only');root.querySelector('[data-reopen]').focus()})});
mb.addEventListener('click',function(){var o=ck.classList.toggle('more');mb.setAttribute('aria-expanded',o);mb.textContent=o?'Save choices':'Preferences';if(!o)hide('Preferences saved')});
root.querySelector('[data-reopen]').addEventListener('click',function(){ck.classList.remove('hide','more');ck.removeAttribute('aria-hidden');mb.textContent='Preferences';mb.setAttribute('aria-expanded','false');msg.classList.remove('on');root.querySelector('[data-a]').focus()})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
